    def gam( T, P, FAR ):
        return interp3D( FAR, P, T, air2.FAR_TP, air2.P_TP, air2.T_TP, air2.gam_TPt ) 
        
    def rho( T, P, FAR ):
        return interp3D( FAR, P, T, air2.FAR_TP, air2.P_TP, air2.T_TP, air2.rho_TPt ) 
        
    def Cp( T, P, FAR ):
        return interp3D( FAR, P, T, air2.FAR_TP, air2.P_TP, air2.T_TP, air2.Cp_TPt ) 

    def h_TP( T, P, FAR ):
        return interp3D( FAR, P, T, air2.FAR_TP, air2.P_TP, air2.T_TP, air2.h_TPt ) 

    def s_TP( T, P, FAR ):
        return interp3D( FAR, P, T, air2.FAR_TP, air2.P_TP, air2.T_TP, air2.s_TPt )

    def R( T, P, FAR ):
        return interp3D( FAR, P, T, air2.FAR_TP, air2.P_TP, air2.T_TP, air2.R_TPt )

    def mu( T, P, FAR ):
        return 0
        
    def k( T, P, FAR ):
    	return 0
    	
    def T_sP( s, P, FAR ):
    	T = 1500
    	scalc = air2.s_TP( T, P, FAR )

    	errorm1 = ( scalc - s )/s
    	xm1 =  T
    	T = T*.95
    	scalc = air2.s_TP( T, P, FAR )    
    	error = ( scalc - s )/ s
    	x = T
    	while abs( error ) > .0000001:
    		xp1 = x - error * (x - xm1 ) / ( error - errorm1 )
    		if xp1 - x > .3*T:
    			xp1 = x + .3*T    			
    		if xp1 - x < -.3*T:
    			xp1 = x - .3*T
    		xm1 = x
    		errorm1 = error
    		x = xp1
    		T = x
    		scalc = air2.s_TP( T, P, FAR )
    		error = ( scalc - s )/ s

    	return T			

    def T_hP( h, P, FAR ):
    	T = 1500
    	hcalc = air2.h_TP( T, P, FAR )
    	errorm1 = ( hcalc - h )/h
    	xm1 =  T
    	T = T*.95
    	hcalc = air2.h_TP( T, P, FAR )    
    	error = ( hcalc - h )/ h
    	x = T
    	while abs( error ) > .000001:
    		
    		xp1 = x - error * (x - xm1 ) / ( error - errorm1 )
    		if xp1 - x > .3*T:
    			xp1 = x + .3*T    			
    		if xp1 - x < -.3*T:
    			xp1 = x - .3*T
    		xm1 = x
    		errorm1 = error
    		x = xp1
    		T = x
    		hcalc = air2.h_TP( T, P, FAR )
    		error = ( hcalc - h )/ h
    
    		
    	return T 